<script setup lang="ts">
import { IonContent, IonPage, onIonViewWillEnter } from '@ionic/vue'
import { ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import type { User } from '@/types'
import { userService } from '@/services/user'
import UserBasicInfo from '@/components/UserBasicInfo.vue'
import SekaiGrid from '@/components/SekaiGrid.vue'
import { useToastStore } from '@/store/toast'
import HeaderWithReturn from '@/components/HeaderWithReturn.vue'

const user = ref<User>()
const route = useRoute()
const toastStore = useToastStore()
const userId = ref(route.query.userId as string)
// -1: No follow between the two users
// 0: login user follows this user
// 1: this user follows login user
// 2: mutual follow
const followStatus = ref(-1)

onIonViewWillEnter(async () => {
  fetchUser()
})

watch(
  () => route.query.userId,
  async (newUserId) => {
    userId.value = newUserId as string
    await fetchUser()
  },
)

async function fetchUser() {
  const { user: res, followStatus: newFollowStatus } = (
    await userService.getUserInfo(userId.value)
  ).data
  user.value = {
    userId: res.userId,
    userName: res.userName,
    userDescription: '',
    userAvatarUrl: res.avatarUrl,
    favoriteUniverseCount: res.favoriteUniverseCount,
    createUniverseCount: res.createUniverseCount,
    followerCount: res.followerCount,
    followingCount: res.followingCount,
  }
  followStatus.value = newFollowStatus
}

async function followOperation(userId: number, isFollow: boolean) {
  try {
    await userService.followOperations(
      userId,
      isFollow ? 'follow' : 'unfollow',
    )

    toastStore.setToast(
      isFollow ? 'Follow successfully' : 'Unfollow successfully',
    )
  }
  catch (error) {
    console.error(error)
  }
}
</script>

<template>
  <ion-page>
    <header-with-return :title="user?.userName || ''" />
    <ion-content>
      <div class="h-4" />
      <user-basic-info
        v-if="user"
        :key="user.userId"
        :user="user"
        :me="false"
      />
      <div class="w-full px-4">
        <!-- show follow when status is -1 -->
        <!-- show follow back when status is 1 -->
        <!-- show following when status is 0 or 2 -->

        <button
          v-if="user"
          :class="`${
            followStatus === 0 || followStatus === 2
              ? 'btn-secondary'
              : 'btn-primary'
          } mt-4 mb-2 h-8`"
          @click="() => followOperation(user!.userId, followStatus === -1 || followStatus === 1)"
        >
          {{
            followStatus === -1
              ? "Follow"
              : followStatus === 1
                ? "Follow Back"
                : "Following"
          }}
        </button>
      </div>
      <sekai-grid :user-id="userId" />
    </ion-content>
  </ion-page>
</template>
